                    return Js.Cat("<tr><td>", Shared.esc(s.Get("name")).Str(), "</td><td>", Shared.esc(s.Get("sign")).Str(), " ", Shared.esc(s.Get("dms")).Str(), "</td><td>", Shared.esc(s.Get("lord")).Str(), "</td></tr>");
                })).Join(Js.S("\n"));
                Js pvRows = Shared.listOf(y.Get("panchavargeeya")).Map(Js.Fn(args2_ =>
                {
                    Js p = Js.Arg(args2_, 0);
                    return Js.Cat("<tr><td>", Shared.esc(p.Get("planet")).Str(), "</td><td>", Shared.esc((p.Get("vishwa").NonNullish ?? Js.N(0d)).ToFixed(Js.N(2d))).Str(), "</td></tr>");
                })).Join(Js.S("\n"));
                return Js.Cat("<h3>", Shared.esc(label.Call(Js.S("varshaphal_year"))).Str(), " ", Shared.esc(y.Get("year")).Str(), "</h3>\n<p><strong>", Shared.esc(label.Call(Js.S("varshaphal_muntha"))).Str(), ":</strong> ", Shared.esc(y.Get("muntha_sign")).Str(), " (", Shared.esc(label.Call(Js.S("house"))).Str(), " ", Shared.esc(y.Get("muntha_house")).Str(), ") &nbsp;\n<strong>", Shared.esc(label.Call(Js.S("varshaphal_lord"))).Str(), ":</strong> ", Shared.esc(y.Get("varsha_lord")).Str(), "</p>\n", (y.Get("summary") ? Js.Cat("<p>", Shared.escBody(y.Get("summary"), locale).Str(), "</p>") : Js.S("")).Str(), "\n", (sahamRows ? Js.Cat("<h4>", Shared.esc(label.Call(Js.S("varshaphal_sahams"))).Str(), "</h4>", KundliBrihadSections.table(Js.Arr(label.Call(Js.S("varshaphal_saham")), label.Call(Js.S("sign")), label.Call(Js.S("lord"))), Js.Arr(sahamRows)).Str()) : Js.S("")).Str(), "\n", (pvRows ? Js.Cat("<h4>", Shared.esc(label.Call(Js.S("varshaphal_panchavargeeya"))).Str(), "</h4>", KundliBrihadSections.table(Js.Arr(label.Call(Js.S("planet")), label.Call(Js.S("varshaphal_vishwa"))), Js.Arr(pvRows)).Str()) : Js.S("")).Str());
            })).Join(Js.S("\n<hr>\n"));
            return Js.Cat("<section class=\"section\">\n<h2>", Shared.esc(label.Call(Js.S("section_varshaphal"))).Str(), "</h2>\n<p>", Shared.esc(label.Call(Js.S("varshaphal_intro"))).Str(), "</p>\n", blocks.Str(), "\n</section>");
        }

        internal static Js renderMuddaTimeline(Js label, Js t, Js locale)
        {
            locale = locale.OrDefault(Js.S("en"));
            if ((((!t) || (!Js.IsArray(t.Get("periods")))) || Js.StrictEquals(t.Get("periods").Get("length"), Js.N(0d))))
            {
                return Js.S("");
            }
            Js cards = t.Get("periods").Map(Js.Fn(args1_ =>
            {
                Js p = Js.Arg(args1_, 0);
                Js areas = Shared.listOf(p.Get("areas")).Filter(Js.Fn(args2_ =>
                {
                    Js a = Js.Arg(args2_, 0);
                    return a.Get("text");
                })).Map(Js.Fn(args2_ =>
                {
                    Js a2 = Js.Arg(args2_, 0);
                    return Js.Cat("<p class=\"mudda-area\"><strong>", Shared.esc(a2.Get("label")).Str(), ":</strong> ", Shared.escBody(a2.Get("text"), locale).Str(), "</p>");
                })).Join(Js.S("\n"));
                Js guidance = Js.Cat("<div class=\"mudda-guidance\">\n", (p.Get("do") ? Js.Cat("<p><strong>", Shared.esc(p.Get("do_label")).Str(), ":</strong> ", Shared.escBody(p.Get("do"), locale).Str(), "</p>") : Js.S("")).Str(), "\n", (p.Get("avoid") ? Js.Cat("<p><strong>", Shared.esc(p.Get("avoid_label")).Str(), ":</strong> ", Shared.escBody(p.Get("avoid"), locale).Str(), "</p>") : Js.S("")).Str(), "\n", (p.Get("remedy") ? Js.Cat("<p><strong>", Shared.esc(p.Get("remedy_label")).Str(), ":</strong> ", Shared.escBody(p.Get("remedy"), locale).Str(), "</p>") : Js.S("")).Str(), "\n</div>");
                return Js.Cat("<div class=\"mudda-period\">\n<h3 class=\"mudda-head\">", Shared.esc(p.Get("date_from")).Str(), " ", Shared.esc((label.Call(Js.S("varshaphal_to")) || Js.S("–"))).Str(), " ", Shared.esc(p.Get("date_to")).Str(), " &nbsp;·&nbsp; ", Shared.esc(p.Get("lord")).Str(), "</h3>\n", (p.Get("summary") ? Js.Cat("<p class=\"mudda-summary\">", Shared.escBody(p.Get("summary"), locale).Str(), "</p>") : Js.S("")).Str(), "\n", areas.Str(), "\n", guidance.Str(), "\n</div>");
            })).Join(Js.S("\n"));
            Js yr = (t.Get("year") ? Js.Cat(" ", Shared.esc(t.Get("year")).Str()) : Js.S(""));
            return Js.Cat("<section class=\"section mudda-section\">\n<h2>", Shared.esc((t.Get("heading") || label.Call(Js.S("section_mudda")))).Str(), yr.Str(), "</h2>\n", cards.Str(), "\n</section>");
        }

        internal static Js renderRajyoga(Js label, Js r)
        {
            if ((!r))
            {
                return Js.S("");
            }
            Js skRows = Shared.listOf(r.Get("swarnim_kaal")).Map(Js.Fn(args1_ =>
            {
                Js p = Js.Arg(args1_, 0);
                return Js.Cat("<tr><td>", Shared.esc(p.Get("lord")).Str(), "</td><td>", Shared.esc(p.Get("start")).Str(), "</td><td>", Shared.esc(p.Get("end")).Str(), "</td></tr>");
            })).Join(Js.S("\n"));
            return Js.Cat("<section class=\"section", (Js.LessOrEqual(Shared.listOf(r.Get("swarnim_kaal")).Get("length"), Js.N(2d)) ? Js.S(" short-section") : Js.S("")).Str(), "\">\n<h2>", Shared.esc(label.Call(Js.S("section_rajyoga"))).Str(), "</h2>\n<div class=\"rajyoga-power\">\n<div class=\"rajyoga-pct\">", Shared.esc(r.Get("percent")).Str(), "%</div>\n<div class=\"rajyoga-label\">", Shared.esc(label.Call(Js.S("rajyoga_strength"))).Str(), "</div>\n</div>\n<p>", Shared.esc(label.Call(Js.S("rajyoga_planets"))).Str(), ": ", Shared.esc(Shared.listText(r.Get("planets"))).Str(), "</p>\n", (skRows ? Js.Cat("<h3>", Shared.esc(label.Call(Js.S("rajyoga_swarnim"))).Str(), "</h3>", KundliBrihadSections.table(Js.Arr(label.Call(Js.S("planet")), label.Call(Js.S("rajyoga_from")), label.Call(Js.S("rajyoga_to"))), Js.Arr(skRows)).Str()) : Js.S("")).Str(), "\n</section>");
        }

        internal static Js renderBrihadDeepSections(Js label, Js d, Js locale)
        {
            locale = locale.OrDefault(Js.S("en"));
            Js out_ = Js.Arr();
            out_.Push(KundliBrihadSections.renderAvakahada(label, d.Get("avakahada")));
            out_.Push(KundliBrihadSections.renderGhata(label, d.Get("ghata_chakra")));
            out_.Push(KundliBrihadSections.renderChalit(label, d.Get("chalit")));
            out_.Push(KundliBrihadSections.renderShadbala(label, d.Get("shadbala")));
            out_.Push(KundliBrihadSections.renderBhavaBala(label, d.Get("bhava_bala")));
            out_.Push(KundliBrihadSections.renderAshtakavarga(label, d.Get("ashtakavarga")));
            out_.Push(KundliBrihadSections.renderMaitri(label, d.Get("maitri")));
            out_.Push(KundliBrihadSections.renderAvasthas(label, d.Get("avasthas")));
            out_.Push(KundliBrihadSections.renderKP(label, d.Get("kp")));
            out_.Push(KundliBrihadSections.renderJaimini(label, d.Get("jaimini")));
            out_.Push(KundliBrihadSections.renderIshta(label, d.Get("ishta_devata"), locale));
            out_.Push(KundliBrihadSections.renderLalKitab(label, d.Get("lal_kitab")));
            out_.Push(KundliBrihadSections.renderRajyoga(label, d.Get("rajyoga_power")));
            out_.Push(KundliBrihadSections.renderVarshaphal(label, d.Get("varshaphal"), locale));
            out_.Push(KundliBrihadSections.renderMuddaTimeline(label, d.Get("mudda_timeline"), locale));
            foreach (Js t1_ in Shared.listOf(d.Get("narrative_chapters")).Iterate())
            {
                Js ch = t1_;
                if (Js.StrictEquals(ch.Get("key"), Js.S("vistrit_bhavishya")))
                {
                    continue;
                }
                out_.Push(KundliBrihadSections.renderChapter(ch, locale));
            }
            return out_.Filter(Js.Fn(args1_ =>
            {
                Js s = Js.Arg(args1_, 0);
                return Js.Greater(s.Get("length"), Js.N(0d));
            }));
        }

        internal static Js brihadDeepBlocks(Js label, Js d, Js locale)
        {
            locale = locale.OrDefault(Js.S("en"));
            return Js.Obj(
                Js.Prop("avakahada", KundliBrihadSections.renderAvakahada(label, d.Get("avakahada"))),
                Js.Prop("panchang", KundliBrihadSections.renderPanchang(label, d.Get("panchang"))),
                Js.Prop("gems", KundliBrihadSections.renderGems(label, d.Get("gems"))),
                Js.Prop("ghata", KundliBrihadSections.renderGhata(label, d.Get("ghata_chakra"))),
                Js.Prop("chalit", KundliBrihadSections.renderChalit(label, d.Get("chalit"))),
                Js.Prop("shadbala", KundliBrihadSections.renderShadbala(label, d.Get("shadbala"))),
                Js.Prop("bhavabala", KundliBrihadSections.renderBhavaBala(label, d.Get("bhava_bala"))),
                Js.Prop("ashtakavarga", KundliBrihadSections.renderAshtakavarga(label, d.Get("ashtakavarga"))),
                Js.Prop("maitri", KundliBrihadSections.renderMaitri(label, d.Get("maitri"))),
                Js.Prop("avasthas", KundliBrihadSections.renderAvasthas(label, d.Get("avasthas"))),
                Js.Prop("kp", KundliBrihadSections.renderKP(label, d.Get("kp"))),
                Js.Prop("jaimini", KundliBrihadSections.renderJaimini(label, d.Get("jaimini"))),
                Js.Prop("ishta", KundliBrihadSections.renderIshta(label, d.Get("ishta_devata"), locale)),
                Js.Prop("lalkitab", KundliBrihadSections.renderLalKitab(label, d.Get("lal_kitab"))),
                Js.Prop("rajyoga", KundliBrihadSections.renderRajyoga(label, d.Get("rajyoga_power"))),
                Js.Prop("varshaphal", KundliBrihadSections.renderVarshaphal(label, d.Get("varshaphal"), locale)),
                Js.Prop("mudda", KundliBrihadSections.renderMuddaTimeline(label, d.Get("mudda_timeline"), locale)));
        }
    }
}
